import {STMRuntime} from './stm32-runtime.js';
import {decodeBytes} from './unified-project.js';
import {measurementConfig,attachMeasurementRuntime} from './measurement.js';
let runtime,project,running=false,timer,serial='',circuitId=0,traceId=0,tracePins=[],traceLevels={},edges=[],traceDropped=0,measurement,listener;
function stop(){running=false;clearTimeout(timer);}
function observe(cycle,inputs){for(const pin of tracePins){const high=!!inputs[pin];if(traceLevels[pin]!==high){edges.push({pin,cycle,high,...(traceLevels[pin]===undefined?{seed:true}:{})});traceLevels[pin]=high;}}if(edges.length>30000){traceDropped+=edges.length-30000;edges.splice(0,edges.length-30000);}listener?.();}
function configure(d){traceId=d.traceId??traceId;tracePins=(d.pins||tracePins).filter(p=>runtime.board.gpio.includes(p));traceLevels={};edges=[];traceDropped=0;runtime.circuit.onTrace=observe;observe(runtime.circuit.cycle(),runtime.inputs);}
function measurements(d){measurement?.dispose();measurement=attachMeasurementRuntime({cpu:{get cycles(){return runtime.circuit.cycle();}}},{get solution(){return runtime.circuit.solution;},subscribe(fn){listener=fn;return()=>{listener=null;};}},d.measurement||measurementConfig(project),d.measurementId||0);}
function frame(type='snapshot'){const c=runtime.circuit,dc=c.snapshot(),pins=Object.fromEntries(Object.entries(c.pins).map(([p,s])=>[p,{...s,high:!!runtime.inputs[p],voltage:dc.voltages[c.solution.netlist.net(c.board.id+':'+p)]??null}]));const cycles=c.cycle(),base=runtime.board.terminalNumber===2?0x40004400:runtime.board.cpu==='cortex-m4f'?0x40011000:0x40013800,brr=runtime.regs.get(base+8)||0;postMessage({type,bluetooth:c.bluetooth?.snapshot(),circuitId,cycles,seconds:cycles/16000000,pins,running,serial,flashBytes:runtime.image.length,traceId,edges,traceLevels:{...traceLevels},traceDropped,measurement:measurement?.drain(),uart:{baudRate:brr?(base===0x40004400?runtime.board.hz/2:runtime.board.hz)/brr:0,txEnabled:!!(runtime.regs.get(base+12)&8),rxEnabled:!!(runtime.regs.get(base+12)&4)},dc:{...dc,mode:'synchronous-dc',externalDevices:true,...Object.fromEntries(['ledResults','deviceResults','opampResults','contactResults','sensorResults'].map(k=>[k,Object.fromEntries(c.solution[k]||[])]))},i2c:{modules:dc.devices,displays:Object.fromEntries(Object.entries(dc.devices).filter(([,d])=>d.type==='oled'))},spi:{devices:dc.devices}});serial='';edges=[];traceDropped=0;}
function tick(){if(!running)return;try{const t=performance.now();do{serial+=runtime.step(1000);}while(performance.now()-t<10);frame();timer=setTimeout(tick,0);}catch(e){stop();postMessage({type:'error',message:e.message});}}
self.onmessage=async({data:d})=>{try{switch(d.type){case 'load':stop();runtime?.dispose();project=d.circuit;circuitId=d.circuitId;runtime=await new STMRuntime(decodeBytes(d.hex),{chip:d.chip}).load();runtime.attachCircuit(project);configure(d);measurements(d);frame('ready');break;case 'run':stop();running=true;tick();break;case 'pause':stop();frame();break;case 'step':stop();serial+=runtime.step(10000);frame();break;case 'reset':stop();runtime.reset();serial='';configure(d);measurements(d);frame();break;case 'circuit':project=d.circuit;circuitId=d.circuitId;runtime.circuit.update(project);frame();break;case 'usb':{try{if(!runtime)throw Error('Önce USB firmware’ini başlatın.');if(!['reset','setup','out','in'].includes(d.op))throw Error('USB komutu geçersiz.');if(!Number.isInteger(d.address??0)||(d.address??0)<0||(d.address??0)>127||!Number.isInteger(d.endpoint??0)||(d.endpoint??0)<0||(d.endpoint??0)>7)throw Error('USB adres/endpoint geçersiz.');if(d.op==='reset'||d.op==='in'){}else if(!Array.isArray(d.data)||d.data.length>64||d.data.some(n=>!Number.isInteger(n)||n<0||n>255))throw Error('USB paket verisi geçersiz.');const u=runtime.usb;let p;if(d.op==='reset')p={status:u.hostReset()};else if(d.op==='in')p=u.hostIn(d.address,d.endpoint);else p={status:u.hostOut(d.address,d.endpoint,Uint8Array.from(d.data),d.op==='setup')};serial+=runtime.step(10000);postMessage({type:'usb',requestId:d.requestId,...p,...(p.data?{data:[...p.data]}:{})});frame();}catch(e){postMessage({type:'usb',requestId:d.requestId,error:e.message});}break;}case 'bluetooth':{try{const scan=runtime.circuit.bluetoothCommand(d);postMessage({type:'bluetooth',bluetooth:runtime.circuit.bluetooth.snapshot(),scan});}catch(e){postMessage({type:'bluetooth-error',message:e.message});}break;}case 'serial':try{runtime.queueSerial(d.text);}catch(e){postMessage({type:'serial-error',message:e.message});}break;case 'probe':configure(d);frame();break;case 'measurement':measurements(d);frame();break;case 'trace':break;default:throw Error('Bilinmeyen STM32 çalışma komutu.');}}catch(e){stop();postMessage({type:'error',message:e.message});}};
